import React, { useState, useEffect, useContext } from 'react';
import { useNavigate } from 'react-router-dom';
import Navbar from '../components/Navbar';
import { AuthContext } from '../context/AuthContext';
import { API_URL } from '../config';

const EMPTY_COURSE = {
  title: '', description: '', price: 0, is_free: false, category: 'Réseau & Défense',
  status: 'draft', thumbnail_url: '', instructor_name: '', lessons: []
};

const PaymentSettingsSection = ({ authHeaders }) => {
  const [methods, setMethods] = useState([]);
  const [uploading, setUploading] = useState(null);
  const [saveMsg, setSaveMsg] = useState('');

  const load = () => {
    fetch(`${API_URL}/payment-methods/all`, { headers: authHeaders })
      .then(res => res.ok ? res.json() : [])
      .then(setMethods);
  };

  useEffect(() => { load(); }, []);

  const updateField = (key, field, value) => {
    setMethods(methods.map(m => m.key === key ? { ...m, [field]: value } : m));
  };

  const handleLogoUpload = async (key, file) => {
    if (!file) return;
    setUploading(key);
    try {
      const formData = new FormData();
      formData.append('file', file);
      const res = await fetch(`${API_URL}/uploads/image`, {
        method: 'POST',
        headers: authHeaders,
        body: formData,
      });
      const data = await res.json();
      updateField(key, 'logo_url', `${API_URL}${data.url}`);
    } catch {
      alert("Échec de l'import du logo.");
    } finally {
      setUploading(null);
    }
  };

  const saveMethod = async (m) => {
    await fetch(`${API_URL}/payment-methods/${m.key}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json', ...authHeaders },
      body: JSON.stringify({
        display_name: m.display_name,
        logo_url: m.logo_url,
        receiving_info: m.receiving_info,
        enabled: m.enabled,
      }),
    });
    setSaveMsg(`✓ ${m.display_name} enregistré.`);
    setTimeout(() => setSaveMsg(''), 2500);
  };

  return (
    <div className="bg-slate-900/60 border border-slate-800 rounded-2xl p-6 space-y-6">
      <h3 className="text-sm font-bold text-white">Réglages des moyens de paiement</h3>
      {saveMsg && (
        <div className="bg-emerald-500/10 border border-emerald-500/30 text-emerald-400 text-sm rounded-lg px-4 py-3">{saveMsg}</div>
      )}
      <div className="space-y-4">
        {methods.map((m) => (
          <div key={m.key} className="bg-slate-950 border border-slate-800 rounded-lg p-4 space-y-3">
            <div className="flex items-center justify-between">
              <span className="text-xs font-bold uppercase text-slate-400">{m.key}</span>
              <label className="flex items-center gap-2 text-xs text-slate-400">
                <input type="checkbox" checked={m.enabled} onChange={(e) => updateField(m.key, 'enabled', e.target.checked)} className="accent-blue-500" />
                Actif
              </label>
            </div>
            <div className="grid md:grid-cols-2 gap-3">
              <input
                type="text" placeholder="Nom affiché" value={m.display_name}
                onChange={(e) => updateField(m.key, 'display_name', e.target.value)}
                className="bg-slate-900 border border-slate-800 px-3 py-2 text-xs rounded-lg text-white outline-none focus:border-blue-500"
              />
              <input
                type="text" placeholder="Infos de réception (numéro, email, ID marchand...)" value={m.receiving_info || ''}
                onChange={(e) => updateField(m.key, 'receiving_info', e.target.value)}
                className="bg-slate-900 border border-slate-800 px-3 py-2 text-xs rounded-lg text-white outline-none focus:border-blue-500"
              />
            </div>
            <div className="flex items-center gap-3">
              {m.logo_url && <img src={m.logo_url} alt="" className="h-8 object-contain bg-white/5 rounded px-2 py-1" />}
              <label className="bg-slate-900 border border-slate-800 hover:border-blue-500 text-slate-300 hover:text-blue-400 px-3 py-2 rounded-lg text-[10px] font-semibold uppercase cursor-pointer transition-colors">
                {uploading === m.key ? 'Import...' : 'Choisir un logo'}
                <input type="file" accept="image/*" onChange={(e) => handleLogoUpload(m.key, e.target.files[0])} className="hidden" disabled={uploading === m.key} />
              </label>
              <button onClick={() => saveMethod(m)} className="ml-auto bg-blue-600 hover:bg-blue-500 text-white text-xs font-semibold px-4 py-2 rounded-lg transition-colors">
                Enregistrer
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

const AdminDashboard = () => {
  const { token, loading } = useContext(AuthContext);
  const navigate = useNavigate();
  const authHeaders = { Authorization: `Bearer ${token}` };

  const [summary, setSummary] = useState(null);
  const [messages, setMessages] = useState([]);
  const [courses, setCourses] = useState([]);
  const [users, setUsers] = useState([]);
  const [transactions, setTransactions] = useState([]);
  const [selectedCourseId, setSelectedCourseId] = useState('new');
  const [courseToEdit, setCourseToEdit] = useState(EMPTY_COURSE);
  const [isSaving, setIsSaving] = useState(false);
  const [saveMessage, setSaveMessage] = useState('');
  const [uploadingThumb, setUploadingThumb] = useState(false);
  const [uploadingVideo, setUploadingVideo] = useState(null);

  useEffect(() => {
    if (!loading && !token) navigate('/login');
  }, [token, loading]);

  const loadCourses = () => {
    fetch(`${API_URL}/courses/all`, { headers: authHeaders })
      .then(res => res.ok ? res.json() : [])
      .then(setCourses);
  };

  useEffect(() => {
    if (!token) return;

    fetch(`${API_URL}/payments/admin/summary`, { headers: authHeaders })
      .then(res => res.ok ? res.json() : null)
      .then(setSummary);

    fetch(`${API_URL}/contact/`, { headers: authHeaders })
      .then(res => res.ok ? res.json() : [])
      .then(setMessages);

    fetch(`${API_URL}/admin/users`, { headers: authHeaders })
      .then(res => res.ok ? res.json() : [])
      .then(setUsers);

    fetch(`${API_URL}/admin/transactions`, { headers: authHeaders })
      .then(res => res.ok ? res.json() : [])
      .then(setTransactions);

    loadCourses();
  }, [token]);

  const handleCourseSelect = (value) => {
    setSelectedCourseId(value);
    if (value === 'new') {
      setCourseToEdit(EMPTY_COURSE);
    } else {
      const c = courses.find(c => c.id === parseInt(value));
      setCourseToEdit(c);
    }
  };

  const handleThumbnailUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    setUploadingThumb(true);
    try {
      const formData = new FormData();
      formData.append('file', file);
      const res = await fetch(`${API_URL}/uploads/image`, {
        method: 'POST',
        headers: authHeaders,
        body: formData,
      });
      if (!res.ok) throw new Error();
      const data = await res.json();
      setCourseToEdit({ ...courseToEdit, thumbnail_url: `${API_URL}${data.url}` });
    } catch {
      alert("Échec de l'import de l'image.");
    } finally {
      setUploadingThumb(false);
    }
  };

  const handleVideoUpload = async (lessonId, file) => {
    if (!file) return;
    setUploadingVideo(lessonId);
    try {
      const formData = new FormData();
      formData.append('file', file);
      const res = await fetch(`${API_URL}/uploads/video`, {
        method: 'POST',
        headers: authHeaders,
        body: formData,
      });
      if (!res.ok) throw new Error();
      const data = await res.json();
      updateLesson(lessonId, 'video_url', `${API_URL}${data.url}`);
    } catch {
      alert("Échec de l'import de la vidéo.");
    } finally {
      setUploadingVideo(null);
    }
  };

  const addLesson = () => {
    setCourseToEdit({
      ...courseToEdit,
      lessons: [...(courseToEdit.lessons || []), { id: `new-${Date.now()}`, title: '', duration: '00:00', video_url: '' }]
    });
  };

  const updateLesson = (lessonId, field, value) => {
    setCourseToEdit({
      ...courseToEdit,
      lessons: courseToEdit.lessons.map(l => l.id === lessonId ? { ...l, [field]: value } : l)
    });
  };

  const removeLesson = async (lessonId) => {
    if (typeof lessonId === 'number' && selectedCourseId !== 'new') {
      await fetch(`${API_URL}/courses/${selectedCourseId}/lessons/${lessonId}`, {
        method: 'DELETE',
        headers: authHeaders,
      });
    }
    setCourseToEdit({ ...courseToEdit, lessons: courseToEdit.lessons.filter(l => l.id !== lessonId) });
  };

  const saveCourse = async (status) => {
    setIsSaving(true);
    setSaveMessage('');
    const payload = {
      title: courseToEdit.title,
      description: courseToEdit.description,
      price: parseInt(courseToEdit.price) || 0,
      is_free: courseToEdit.is_free,
      category: courseToEdit.category,
      status,
      thumbnail_url: courseToEdit.thumbnail_url,
      instructor_name: courseToEdit.instructor_name,
    };

    try {
      let savedCourse;
      if (selectedCourseId === 'new') {
        const res = await fetch(`${API_URL}/courses/`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', ...authHeaders },
          body: JSON.stringify(payload),
        });
        savedCourse = await res.json();
      } else {
        const res = await fetch(`${API_URL}/courses/${selectedCourseId}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json', ...authHeaders },
          body: JSON.stringify(payload),
        });
        savedCourse = await res.json();
      }

      for (const lesson of courseToEdit.lessons || []) {
        if (typeof lesson.id === 'string' && lesson.id.startsWith('new-')) {
          await fetch(`${API_URL}/courses/${savedCourse.id}/lessons`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', ...authHeaders },
            body: JSON.stringify({ title: lesson.title, duration: lesson.duration, video_url: lesson.video_url, order: 0 }),
          });
        }
      }

      setSaveMessage(status === 'published' ? '✓ Cours publié.' : '✓ Brouillon enregistré.');
      loadCourses();
      setSelectedCourseId(savedCourse.id.toString());
      setTimeout(() => setSaveMessage(''), 3000);
    } catch {
      setSaveMessage('Erreur lors de la sauvegarde.');
    } finally {
      setIsSaving(false);
    }
  };

  const deleteCourse = async () => {
    if (selectedCourseId === 'new') return;
    if (!window.confirm(`Supprimer définitivement "${courseToEdit.title}" ? Cette action est irréversible.`)) return;

    await fetch(`${API_URL}/courses/${selectedCourseId}`, { method: 'DELETE', headers: authHeaders });
    loadCourses();
    setSelectedCourseId('new');
    setCourseToEdit(EMPTY_COURSE);
  };

  const resolveMessage = async (id) => {
    await fetch(`${API_URL}/contact/${id}/resolve`, { method: 'PUT', headers: authHeaders });
    setMessages(messages.map(m => m.id === id ? { ...m, resolved: true } : m));
  };

  const formatDate = (isoString) => {
    return new Date(isoString).toLocaleDateString('fr-FR', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
  };

  if (loading || !token) {
    return <div className="min-h-screen bg-[#0A0E1A] flex items-center justify-center text-slate-500 text-sm">Chargement...</div>;
  }

  return (
    <div className="min-h-screen bg-[#0A0E1A] text-slate-200">
      <Navbar />

      <div className="max-w-5xl mx-auto px-6 py-12 space-y-10">

        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 border-b border-slate-800 pb-8">
          <div>
            <span className="text-[11px] font-semibold text-blue-400 tracking-wide uppercase">Console de gestion</span>
            <h1 className="text-2xl font-bold text-white mt-1">Panneau d'administration</h1>
          </div>
          {selectedCourseId !== 'new' && (
            <span className={`text-[11px] font-bold uppercase tracking-wide px-3 py-1.5 rounded-full ${
              courseToEdit.status === 'published' ? 'bg-emerald-500/10 text-emerald-400' : 'bg-amber-500/10 text-amber-400'
            }`}>
              {courseToEdit.status === 'published' ? 'Publié' : 'Brouillon'}
            </span>
          )}
        </div>

        {summary && (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
            <div className="bg-slate-900/60 border border-slate-800 rounded-2xl p-6">
              <p className="text-[11px] uppercase text-slate-500 font-semibold tracking-wide">Chiffre d'affaires total</p>
              <p className="text-xl font-bold mt-2 text-white">{summary.total_revenue.toLocaleString()} FCFA</p>
            </div>
            <div className="bg-slate-900/60 border border-slate-800 rounded-2xl p-6">
              <p className="text-[11px] uppercase text-slate-500 font-semibold tracking-wide">Meilleure vente</p>
              <p className="text-sm mt-2 font-bold text-white">{summary.top_course.title || '—'} · {summary.top_course.sales} ventes</p>
            </div>
            <div className="bg-slate-900/60 border border-slate-800 rounded-2xl p-6">
              <p className="text-[11px] uppercase text-slate-500 font-semibold tracking-wide">Répartition paiement</p>
              <p className="text-sm mt-2 font-bold text-white">
                {Object.entries(summary.payment_breakdown).map(([k, v]) => `${k.toUpperCase()} ${v}`).join(' · ') || 'Aucune vente'}
              </p>
            </div>
          </div>
        )}

        <div className="bg-slate-900/60 border border-slate-800 rounded-2xl p-6 space-y-6">
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
            <h3 className="text-sm font-bold text-white">Gestion des cours</h3>
            <div className="flex items-center gap-3">
              <select
                value={selectedCourseId}
                onChange={(e) => handleCourseSelect(e.target.value)}
                className="bg-slate-950 border border-slate-800 text-white text-xs px-3 py-2 rounded-lg outline-none"
              >
                <option value="new">+ Nouveau cours</option>
                {courses.map(c => (
                  <option key={c.id} value={c.id}>
                    {c.title} {c.status === 'draft' ? '(brouillon)' : ''}
                  </option>
                ))}
              </select>
              {selectedCourseId !== 'new' && (
                <button onClick={deleteCourse} className="text-red-400 hover:text-red-300 text-xs font-semibold uppercase">
                  Supprimer le cours
                </button>
              )}
            </div>
          </div>

          {saveMessage && (
            <div className="bg-emerald-500/10 border border-emerald-500/30 text-emerald-400 text-sm rounded-lg px-4 py-3">
              {saveMessage}
            </div>
          )}

          <div className="grid md:grid-cols-2 gap-4">
            <input
              type="text" placeholder="Titre du cours" value={courseToEdit.title || ''}
              onChange={(e) => setCourseToEdit({ ...courseToEdit, title: e.target.value })}
              className="bg-slate-950 border border-slate-800 rounded-lg px-4 py-3 text-sm text-white outline-none focus:border-blue-500 transition-colors"
            />
            <input
              type="text" placeholder="Nom du formateur" value={courseToEdit.instructor_name || ''}
              onChange={(e) => setCourseToEdit({ ...courseToEdit, instructor_name: e.target.value })}
              className="bg-slate-950 border border-slate-800 rounded-lg px-4 py-3 text-sm text-white outline-none focus:border-blue-500 transition-colors"
            />
          </div>

          <textarea
            placeholder="Description du cours" rows="3" value={courseToEdit.description || ''}
            onChange={(e) => setCourseToEdit({ ...courseToEdit, description: e.target.value })}
            className="w-full bg-slate-950 border border-slate-800 rounded-lg px-4 py-3 text-sm text-white outline-none focus:border-blue-500 transition-colors resize-none"
          ></textarea>

          <div className="grid md:grid-cols-3 gap-4">
            <select
              value={courseToEdit.category || 'Réseau & Défense'}
              onChange={(e) => setCourseToEdit({ ...courseToEdit, category: e.target.value })}
              className="bg-slate-950 border border-slate-800 rounded-lg px-4 py-3 text-sm text-white outline-none"
            >
              <option value="Réseau & Défense">Réseau & Défense</option>
              <option value="Hacking Offensif">Hacking Offensif</option>
            </select>

            <label className="flex items-center gap-2 bg-slate-950 border border-slate-800 rounded-lg px-4 py-3 text-sm text-white cursor-pointer">
              <input
                type="checkbox" checked={courseToEdit.is_free || false}
                onChange={(e) => setCourseToEdit({ ...courseToEdit, is_free: e.target.checked })}
                className="accent-blue-500"
              />
              Cours gratuit
            </label>

            {!courseToEdit.is_free && (
              <input
                type="number" placeholder="Prix (FCFA)" value={courseToEdit.price || ''}
                onChange={(e) => setCourseToEdit({ ...courseToEdit, price: e.target.value })}
                className="bg-slate-950 border border-slate-800 rounded-lg px-4 py-3 text-sm text-white outline-none focus:border-blue-500 transition-colors"
              />
            )}
          </div>

          <div>
            <label className="text-xs font-semibold text-slate-500 uppercase tracking-wide mb-2 block">Image de couverture</label>
            <div className="flex items-center gap-4">
              {courseToEdit.thumbnail_url && (
                <img src={courseToEdit.thumbnail_url} alt="" className="w-24 h-16 object-cover rounded-lg border border-slate-800" />
              )}
              <label className="bg-slate-950 border border-slate-800 hover:border-blue-500 text-slate-300 hover:text-blue-400 px-4 py-2.5 rounded-lg text-xs font-semibold uppercase cursor-pointer transition-colors">
                {uploadingThumb ? 'Import en cours...' : 'Choisir une image sur mon PC'}
                <input type="file" accept="image/*" onChange={handleThumbnailUpload} className="hidden" disabled={uploadingThumb} />
              </label>
            </div>
          </div>

          <div className="space-y-3 pt-4 border-t border-slate-800">
            <div className="flex justify-between items-center">
              <span className="text-xs font-semibold text-slate-500 uppercase tracking-wide">
                Programme ({(courseToEdit.lessons || []).length} leçons)
              </span>
              <button onClick={addLesson} className="text-xs text-blue-400 hover:text-blue-300 font-semibold">+ Ajouter une leçon</button>
            </div>
            {(courseToEdit.lessons || []).map((lesson) => (
              <div key={lesson.id} className="bg-slate-950 p-4 rounded-lg border border-slate-800 space-y-3">
                <div className="grid md:grid-cols-12 gap-3 items-center">
                  <input
                    className="md:col-span-6 bg-slate-900 border border-slate-800 px-3 py-2 text-xs rounded-lg text-white outline-none focus:border-blue-500"
                    value={lesson.title} onChange={(e) => updateLesson(lesson.id, 'title', e.target.value)} placeholder="Titre de la leçon"
                  />
                  <input
                    className="md:col-span-2 bg-slate-900 border border-slate-800 px-3 py-2 text-xs rounded-lg text-white outline-none focus:border-blue-500"
                    value={lesson.duration} onChange={(e) => updateLesson(lesson.id, 'duration', e.target.value)} placeholder="00:00"
                  />
                  <label className="md:col-span-3 bg-slate-900 border border-slate-800 hover:border-blue-500 text-slate-300 hover:text-blue-400 px-3 py-2 rounded-lg text-[10px] font-semibold uppercase cursor-pointer text-center transition-colors">
                    {uploadingVideo === lesson.id ? 'Import...' : lesson.video_url ? '✓ Vidéo importée' : 'Choisir une vidéo'}
                    <input type="file" accept="video/*" onChange={(e) => handleVideoUpload(lesson.id, e.target.files[0])} className="hidden" disabled={uploadingVideo === lesson.id} />
                  </label>
                  <button onClick={() => removeLesson(lesson.id)} className="md:col-span-1 text-red-400 hover:text-red-300 text-xs font-bold text-center">✕</button>
                </div>
              </div>
            ))}
          </div>

          <div className="flex gap-3 pt-4 border-t border-slate-800">
            <button onClick={() => saveCourse('draft')} disabled={isSaving} className="border border-slate-700 hover:border-slate-500 text-slate-300 hover:text-white font-semibold px-5 py-2.5 rounded-lg text-sm transition-colors">
              Enregistrer comme brouillon
            </button>
            <button onClick={() => saveCourse('published')} disabled={isSaving} className="bg-blue-600 hover:bg-blue-500 text-white font-semibold px-6 py-2.5 rounded-lg text-sm transition-colors">
              {isSaving ? 'Publication...' : 'Publier'}
            </button>
          </div>
        </div>

        <PaymentSettingsSection authHeaders={authHeaders} />

        <div className="bg-slate-900/60 border border-slate-800 rounded-2xl overflow-hidden">
          <div className="p-6 border-b border-slate-800 flex justify-between items-center">
            <h3 className="text-sm font-bold text-white">Transactions ({transactions.length})</h3>
          </div>
          <table className="w-full text-xs text-left">
            <thead className="bg-slate-950 text-slate-500 uppercase">
              <tr><th className="p-4">Étudiant</th><th className="p-4">Cours</th><th className="p-4">Moyen</th><th className="p-4">Date</th></tr>
            </thead>
            <tbody className="divide-y divide-slate-800">
              {transactions.length > 0 ? transactions.map(t => (
                <tr key={t.id}>
                  <td className="p-4 text-slate-300">{t.user_email}</td>
                  <td className="p-4 text-slate-400">{t.course_title}</td>
                  <td className="p-4 text-blue-400 uppercase font-semibold">{t.payment_method || 'Gratuit'}</td>
                  <td className="p-4 text-slate-500">{formatDate(t.created_at)}</td>
                </tr>
              )) : (
                <tr><td colSpan="4" className="p-6 text-center text-slate-600">Aucune transaction pour l'instant.</td></tr>
              )}
            </tbody>
          </table>
        </div>

        <div className="bg-slate-900/60 border border-slate-800 rounded-2xl overflow-hidden">
          <div className="p-6 border-b border-slate-800 flex justify-between items-center">
            <h3 className="text-sm font-bold text-white">Utilisateurs inscrits ({users.length})</h3>
          </div>
          <table className="w-full text-xs text-left">
            <thead className="bg-slate-950 text-slate-500 uppercase">
              <tr><th className="p-4">Nom</th><th className="p-4">Email</th><th className="p-4">Rôle</th><th className="p-4">Inscrit le</th></tr>
            </thead>
            <tbody className="divide-y divide-slate-800">
              {users.map(u => (
                <tr key={u.id}>
                  <td className="p-4 text-slate-300">{u.first_name || '—'} {u.last_name || ''}</td>
                  <td className="p-4 text-slate-400">{u.email}</td>
                  <td className="p-4">
                    <span className={`text-[10px] font-bold uppercase px-2 py-0.5 rounded-full ${u.role === 'admin' ? 'bg-blue-500/10 text-blue-400' : 'bg-slate-800 text-slate-400'}`}>
                      {u.role}
                    </span>
                  </td>
                  <td className="p-4 text-slate-500">{formatDate(u.created_at)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        <div className="bg-slate-900/60 border border-slate-800 rounded-2xl overflow-hidden">
          <div className="p-6 border-b border-slate-800"><h3 className="text-sm font-bold text-white">Messages support</h3></div>
          <table className="w-full text-xs text-left">
            <thead className="bg-slate-950 text-slate-500 uppercase">
              <tr><th className="p-4">Utilisateur</th><th className="p-4">Message</th><th className="p-4">Statut</th></tr>
            </thead>
            <tbody className="divide-y divide-slate-800">
              {messages.map(m => (
                <tr key={m.id}>
                  <td className="p-4 text-slate-300">{m.email}</td>
                  <td className="p-4 text-slate-400">{m.subject}</td>
                  <td className="p-4">
                    {m.resolved ? (
                      <span className="text-emerald-400 uppercase text-[11px] font-semibold">Traité</span>
                    ) : (
                      <button onClick={() => resolveMessage(m.id)} className="text-blue-400 hover:text-blue-300 font-semibold uppercase text-[11px]">Marquer traité</button>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

      </div>
    </div>
  );
};
export default AdminDashboard;
